//! Rust side of the cross-language portable FastDB publish/subscribe proof
//! (ADR 0005). The contract modules are generated by `c2-codegen` at test
//! time from the same `c-two.contract.v2` descriptor the Python test
//! exports, so both languages share one contract identity.
//!
//! Modes (line-oriented JSON on stdout; commands/events on stdin):
//! - `host <ipc_address> <route> <relay_url|->`: mixed-contract Rust host
//!   driven by `publish`/`burst`/`active`/`unregister`/`reregister`/`quit`
//!   commands.
//! - `solo-host <ipc_address> <route>`: 0-method topic-only contract host.
//! - `client <ipc_address> <route>`: Rust client against a Python host,
//!   emitting progress events; waits for one `reregistered` stdin ack.
//! - `solo-client <ipc_address> <route>`: topic-only Rust client.

use std::error::Error;
use std::io::{BufRead, Write};

use c_two::generated::ErrorCode;
use c_two::{
    Connect, Delivery, Error as CTwoError, Held, HostOptions, LagPolicy, Runtime, RuntimeOptions,
    SubscribeOptions, TopicStart,
};
use fastdb::{BuildPolicy, Builder, CompiledSpec, Payload};
use serde_json::{Value, json};

#[path = "../generated-mixed/rust/c_two_contract.rs"]
mod mixed;
#[path = "../generated-solo/rust/c_two_contract.rs"]
mod solo;

const SPEC: &[u8] = br#"{
    "schema": "fastdb.payload.v1",
    "profile": "record.v1",
    "entries": [{"id":"value","cardinality":"one","type":{"kind":"str","nullable":true}}],
    "components": []
}"#;

fn payload(value: &str) -> Payload {
    let spec = CompiledSpec::compile(SPEC).unwrap();
    let mut builder = Builder::create(&spec).unwrap();
    builder.entry_begin(0, 1).unwrap().value_str(value).unwrap();
    builder
        .freeze()
        .unwrap()
        .execute(BuildPolicy::AllowStaging)
        .unwrap()
        .payload
}

fn text(value: &Payload) -> String {
    value
        .entry_view(0)
        .unwrap()
        .at(0)
        .unwrap()
        .acquire()
        .unwrap()
        .str()
        .unwrap()
        .to_string()
}

fn assert_delivery(delivery: &Delivery<Payload>, value: &str, seq: u64, dropped: u64) {
    assert_eq!(text(delivery.value()), value);
    assert_eq!((delivery.seq(), delivery.dropped()), (seq, dropped));
}

fn assert_semantic(error: CTwoError, code: ErrorCode, needle: &str) {
    let CTwoError::Semantic(semantic) = error else {
        panic!("expected {code:?}, got {error:?}");
    };
    assert_eq!(semantic.code, code, "{semantic:?}");
    assert!(
        semantic.message.contains(needle)
            || semantic.details.values().any(|v| v.contains(needle)),
        "unexpected cause in {semantic:?}"
    );
}

fn emit(value: Value) {
    println!("{value}");
    std::io::stdout().flush().unwrap();
}

fn read_line(prompt: &str) -> String {
    let mut line = String::new();
    let count = std::io::stdin().lock().read_line(&mut line).unwrap();
    assert!(count > 0, "unexpected EOF while waiting for {prompt}");
    line.trim().to_string()
}

fn runtime() -> Result<Runtime, c_two::LifecycleError> {
    Runtime::new(RuntimeOptions {
        use_process_relay_anchor: false,
        ..RuntimeOptions::default()
    })
}

// The generated Service trait carries the unary methods; topics stay outside
// the method table, so these hosts implement only what the contract declares.
struct MixedService;
struct SoloHost;

impl mixed::Service for MixedService {
    fn method_0_ping(&self) -> Result<(), CTwoError> {
        Ok(())
    }
}

impl solo::Service for SoloHost {}

fn run_host(address: &str, route: &str, relay: Option<&str>) -> Result<(), Box<dyn Error>> {
    let server_id = address
        .strip_prefix("ipc://")
        .ok_or("Rust host address must use ipc://")?;
    let runtime = runtime()?;
    let mut options = HostOptions::default().with_server_id(server_id);
    options = match relay {
        Some(url) => options.with_relay_anchor_address(url),
        None => options.without_relay(),
    };
    let host = runtime.host(options)?;
    let mut registration = host.register(
        mixed::topic_service(route, MixedService)?
            .topic_0_state_capacity(4)?
            .initial_topic_0_state(&payload("init"))?
            .topic_1_ticks_capacity(2)?
            .build(),
    )?;
    let actual = runtime
        .server_address()
        .ok_or("missing Rust host address")?;
    if actual != address {
        return Err(format!("expected host address {address:?}, got {actual:?}").into());
    }
    emit(json!({"event": "ready", "address": actual}));

    let mut state_publisher = mixed::registration_topics(&registration).topic_0_state()?;
    let mut ticks_publisher = mixed::registration_topics(&registration).topic_1_ticks()?;
    let mut publishes: Vec<(String, u64)> = Vec::new();
    loop {
        let line = read_line("host command");
        let mut fields = line.split_whitespace();
        match fields.next() {
            Some("publish") => {
                let topic = fields.next().ok_or("missing topic")?;
                let value = fields.next().ok_or("missing value")?;
                let seq = match topic {
                    "state" => state_publisher.publish(&payload(value))?,
                    "ticks" => ticks_publisher.publish(&payload(value))?,
                    other => return Err(format!("unknown topic {other:?}").into()),
                };
                publishes.push((topic.to_string(), seq));
                emit(json!({"event": "published", "topic": topic, "seq": seq}));
            }
            Some("burst") => {
                // burst <topic> <prefix> <from> <to>: publish <prefix><i> for
                // i in from..=to back to back, without waiting for subscribers.
                let topic = fields.next().ok_or("missing topic")?;
                let prefix = fields.next().ok_or("missing prefix")?;
                let from: u64 = fields
                    .next()
                    .ok_or("missing burst start")?
                    .parse()
                    .map_err(|e| format!("invalid burst start: {e}"))?;
                let to: u64 = fields
                    .next()
                    .ok_or("missing burst end")?
                    .parse()
                    .map_err(|e| format!("invalid burst end: {e}"))?;
                let mut last = 0;
                for beat in from..=to {
                    let value = format!("{prefix}{beat}");
                    last = match topic {
                        "state" => state_publisher.publish(&payload(&value))?,
                        "ticks" => ticks_publisher.publish(&payload(&value))?,
                        other => return Err(format!("unknown topic {other:?}").into()),
                    };
                    publishes.push((topic.to_string(), last));
                }
                emit(json!({"event": "burst", "topic": topic, "from": from, "to": to, "last_seq": last}));
            }
            Some("active") => {
                emit(json!({"event": "active", "count": registration.active_subscribers()}));
            }
            Some("unregister") => {
                registration.close()?;
                emit(json!({"event": "unregistered"}));
            }
            Some("reregister") => {
                let initial = fields.next().ok_or("missing initial value")?;
                registration = host.register(
                    mixed::topic_service(route, MixedService)?
                        .initial_topic_0_state(&payload(initial))?
                        .build(),
                )?;
                state_publisher = mixed::registration_topics(&registration).topic_0_state()?;
                ticks_publisher = mixed::registration_topics(&registration).topic_1_ticks()?;
                emit(json!({"event": "reregistered"}));
            }
            Some("quit") => break,
            other => return Err(format!("unknown host command {other:?}").into()),
        }
    }
    if !registration.is_closed() {
        registration.close()?;
    }
    drop(host);
    emit(json!({
        "event": "stopped",
        "publishes": publishes,
    }));
    println!("OK rust-host");
    std::io::stdout().flush()?;
    Ok(())
}

fn run_solo_host(address: &str, route: &str) -> Result<(), Box<dyn Error>> {
    let server_id = address
        .strip_prefix("ipc://")
        .ok_or("Rust host address must use ipc://")?;
    let runtime = runtime()?;
    let host = runtime.host(
        HostOptions::default()
            .without_relay()
            .with_server_id(server_id),
    )?;
    let mut registration = host.register(
        solo::topic_service(route, SoloHost)?
            .initial_topic_0_field(&payload("boot"))?
            .build(),
    )?;
    let actual = runtime
        .server_address()
        .ok_or("missing Rust host address")?;
    if actual != address {
        return Err(format!("expected host address {address:?}, got {actual:?}").into());
    }
    emit(json!({"event": "ready", "address": actual}));

    let field_publisher = solo::registration_topics(&registration).topic_0_field()?;
    let mut publishes: Vec<u64> = Vec::new();
    loop {
        let line = read_line("solo host command");
        let mut fields = line.split_whitespace();
        match fields.next() {
            Some("publish") => {
                let topic = fields.next().ok_or("missing topic")?;
                let value = fields.next().ok_or("missing value")?;
                if topic != "field" {
                    return Err(format!("unknown topic {topic:?}").into());
                }
                let seq = field_publisher.publish(&payload(value))?;
                publishes.push(seq);
                emit(json!({"event": "published", "topic": topic, "seq": seq}));
            }
            Some("active") => {
                emit(json!({"event": "active", "count": registration.active_subscribers()}));
            }
            Some("quit") => break,
            other => return Err(format!("unknown solo host command {other:?}").into()),
        }
    }
    registration.close()?;
    drop(host);
    emit(json!({"event": "stopped", "publishes": publishes}));
    println!("OK rust-solo-host");
    std::io::stdout().flush()?;
    Ok(())
}

fn connect_mixed(runtime: &Runtime, address: &str, route: &str) -> Result<mixed::ContractClient, Box<dyn Error>> {
    let core_client = runtime.connect(
        mixed::expected_route(route)?,
        Connect::DirectIpc {
            address: address.to_string(),
        },
    )?;
    Ok(mixed::ContractClient::new(core_client)?)
}

fn run_client(address: &str, route: &str) -> Result<(), Box<dyn Error>> {
    let runtime = runtime()?;
    let client = connect_mixed(&runtime, address, route)?;

    // 1. Atomic initial state with start=Latest, plus the unary method on
    //    the same connection while the subscription is open.
    let state = client.subscribe_topic_0_state(SubscribeOptions {
        start: TopicStart::Latest,
        on_lag: LagPolicy::Skip,
    })?;
    assert_eq!((state.start_seq(), state.topic_name()), (1, "state"));
    let initial = state.next_delivery()?;
    assert_delivery(&initial, "init", 1, 0);
    client.method_0_ping()?;
    emit(json!({"event": "initial-ok"}));

    // 2. Held delivery: owns its local copy through the subscription close.
    let held: Delivery<Held<Payload>> = state.next_delivery_held()?;
    assert_eq!((held.seq(), held.dropped()), (2, 0));
    assert_eq!(text(held.value().value().expect("held payload")), "held-value");

    // 3. start=Next attaches after the current head.
    let following = client.subscribe_topic_0_state(SubscribeOptions {
        start: TopicStart::Next,
        on_lag: LagPolicy::Skip,
    })?;
    assert_eq!(following.start_seq(), 3);
    emit(json!({"event": "next-attached"}));
    let third = following.next_delivery()?;
    assert_delivery(&third, "third", 3, 0);
    assert!(following.close().completed);
    assert!(state.close().completed);
    assert_eq!(
        text(held.value().value().expect("held survived subscription close")),
        "held-value",
        "closed subscription invalidated a delivered hold"
    );
    let (mut held_owner, _, _) = held.into_parts();
    held_owner.release()?;
    assert!(held_owner.value().is_none(), "released hold stayed readable");
    emit(json!({"event": "held-ok"}));

    // 4. Lag policies on the capacity-2 ticks topic.
    let skip = client.subscribe_topic_1_ticks(SubscribeOptions {
        start: TopicStart::Latest,
        on_lag: LagPolicy::Skip,
    })?;
    let strict = client.subscribe_topic_1_ticks(SubscribeOptions {
        start: TopicStart::Latest,
        on_lag: LagPolicy::Error,
    })?;
    emit(json!({"event": "lag-attached"}));
    let first_tick = skip.next_delivery()?;
    assert_delivery(&first_tick, "v1", 1, 0);
    let strict_tick = strict.next_delivery()?;
    assert_delivery(&strict_tick, "v1", 1, 0);
    emit(json!({"event": "ticks-first"}));
    let mut last_seq = 1u64;
    let mut saw_skip = false;
    for _ in 0..8 {
        let delivery = skip.next_delivery()?;
        assert!(delivery.seq() > last_seq);
        if delivery.dropped() > 0 {
            assert_eq!(delivery.seq() - (last_seq + 1), delivery.dropped());
            assert_eq!(text(delivery.value()), format!("v{}", delivery.seq()));
            saw_skip = true;
            break;
        }
        last_seq = delivery.seq();
    }
    assert!(saw_skip, "skip subscriber must report dropped > 0");
    let mut lag_error = None;
    for _ in 0..8 {
        match strict.next_delivery() {
            Ok(delivery) => assert_eq!(delivery.dropped(), 0),
            Err(error) => {
                lag_error = Some(error);
                break;
            }
        }
    }
    let lag_error = lag_error.expect("on_lag=error subscriber must terminate");
    assert_semantic(lag_error, ErrorCode::SubscriptionLagged, "ticks");
    assert!(skip.close().completed);
    assert!(strict.close().completed);
    emit(json!({"event": "lag-ok"}));

    // 5. Python-host unregister ends the live subscription with 718
    //    route_unregistered; the same client follows the re-registered
    //    route with a fresh sequence space.
    let live = client.subscribe_topic_0_state(SubscribeOptions::default())?;
    let retained = live.next_delivery()?;
    assert_delivery(&retained, "third", 3, 0);
    emit(json!({"event": "live-attached"}));
    let ack = read_line("reregistered ack");
    assert_eq!(ack, "reregistered", "unexpected client ack");
    assert_semantic(
        live.next_delivery().unwrap_err(),
        ErrorCode::CallCancelled,
        "route_unregistered",
    );
    assert!(live.close().completed);
    let follower = client.subscribe_topic_0_state(SubscribeOptions::default())?;
    assert_eq!(follower.start_seq(), 1, "sequence restarts with the new registration");
    let reboot = follower.next_delivery()?;
    assert_delivery(&reboot, "r2-init", 1, 0);
    emit(json!({"event": "refollow-ok"}));
    let post = follower.next_delivery()?;
    assert_delivery(&post, "post-reboot", 2, 0);
    assert!(follower.close().completed);
    emit(json!({"event": "done"}));
    println!("OK rust-client");
    std::io::stdout().flush()?;
    Ok(())
}

fn run_solo_client(address: &str, route: &str) -> Result<(), Box<dyn Error>> {
    let runtime = runtime()?;
    let core_client = runtime.connect(
        solo::expected_route(route)?,
        Connect::DirectIpc {
            address: address.to_string(),
        },
    )?;
    let client = solo::ContractClient::new(core_client)?;
    let subscription = client.subscribe_topic_0_field(SubscribeOptions::default())?;
    assert_eq!((subscription.start_seq(), subscription.topic_name()), (1, "field"));
    let boot = subscription.next_delivery()?;
    assert_delivery(&boot, "boot", 1, 0);
    emit(json!({"event": "solo-initial"}));
    let second = subscription.next_delivery()?;
    assert_delivery(&second, "reading-2", 2, 0);
    assert!(subscription.close().completed);
    emit(json!({"event": "done"}));
    println!("OK rust-solo-client");
    std::io::stdout().flush()?;
    Ok(())
}

fn main() -> Result<(), Box<dyn Error>> {
    let mut args = std::env::args().skip(1);
    let mode = args.next().ok_or("missing mode")?;
    let address = args.next().ok_or("missing IPC address")?;
    let route = args.next().ok_or("missing route name")?;
    match mode.as_str() {
        "host" => {
            let relay = args.next().ok_or("missing relay selection")?;
            let relay = if relay == "-" { None } else { Some(relay.as_str()) };
            run_host(&address, &route, relay)
        }
        "solo-host" => run_solo_host(&address, &route),
        "client" => run_client(&address, &route),
        "solo-client" => run_solo_client(&address, &route),
        other => Err(format!("unknown mode {other:?}").into()),
    }
}
